func coerceSyncBodyParam(value string, typ string) any {
	switch typ {
	case "integer", "int", "int64":
		if parsed, err := strconv.ParseInt(value, 10, 64); err == nil {
			return parsed
		}
	case "number", "float", "float64":
		if parsed, err := strconv.ParseFloat(value, 64); err == nil {
			return parsed
		}
	case "boolean", "bool":
		if parsed, err := strconv.ParseBool(value); err == nil {
			return parsed
		}
	case "array", "json_array":
		// autotask handfix: mirrors the generated query command, which json.Unmarshals the same body
		// field. Without this a --param override reaches the wire as the string "[...]".
		var parsed any
		if err := json.Unmarshal([]byte(value), &parsed); err == nil {
			return parsed
		}
	case "string_csv_array":
		return cliutil.SplitCSV(value)
	}
	return value
}

